/* CommerceForge Dev Docs — Dark Mode Default */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --bg-card: #161b22;
  --border-default: #30363d;
  --border-muted: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00d4aa;
  --accent-hover: #00e6b8;
  --accent-dim: rgba(0, 212, 170, 0.12);
  --accent-glow: rgba(0, 212, 170, 0.25);
  --blue-accent: #58a6ff;
  --blue-dim: rgba(88, 166, 255, 0.12);
  --purple-accent: #bc8cff;
  --purple-dim: rgba(188, 140, 255, 0.12);
  --orange-accent: #f0883e;
  --orange-dim: rgba(240, 136, 62, 0.12);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --transition-fast: 150ms ease;
  --transition-smooth: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.3), 0 0 0 1px rgba(255, 255, 255, 0.05);
  --shadow-elevated: 0 8px 24px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 255, 255, 0.06);
  --max-width: 1280px;
  --sidebar-width: 260px;
  --nav-height: 56px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-hover);
}

img, svg {
  max-width: 100%;
  display: block;
}

/* ===== Scrollbar ===== */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
  background: var(--border-default);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* ===== Top Navigation ===== */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-default);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.nav-brand {
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-brand-icon {
  width: 26px;
  height: 26px;
  border-radius: 6px;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bg-primary);
  font-weight: 800;
  font-size: 14px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-links a {
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.nav-btn {
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
  font-family: var(--font-body);
  white-space: nowrap;
}

.nav-btn:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.nav-btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg-primary);
  font-weight: 600;
}

.nav-btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  color: var(--bg-primary);
}

.nav-hamburger {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 4px;
}

/* ===== Layout ===== */
.page-container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 72px 0;
}

.section-sm {
  padding: 48px 0;
}

.section-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 12px;
}

/* ===== Hero ===== */
.hero {
  padding: 80px 0 64px;
  text-align: center;
}

.hero-inner {
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, #b0bec5 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 640px;
  margin: 0 auto 32px;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 22px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  border: none;
  font-family: var(--font-body);
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: var(--bg-primary);
}

.btn-primary:hover {
  background: var(--accent-hover);
  color: var(--bg-primary);
  box-shadow: 0 0 20px var(--accent-glow);
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  border-color: var(--text-muted);
  color: var(--text-primary);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
}

.btn-ghost:hover {
  color: var(--text-primary);
}

/* ===== Product Cards (Home) ===== */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  transition: all var(--transition-smooth);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
  opacity: 0;
  transition: opacity var(--transition-smooth);
}

.product-card:hover {
  border-color: var(--text-muted);
  box-shadow: var(--shadow-elevated);
  transform: translateY(-2px);
}

.product-card:hover::before {
  opacity: 1;
}

.product-card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  margin-bottom: 16px;
}

.product-card-icon.apps { background: var(--accent-dim); color: var(--accent); }
.product-card-icon.storefronts { background: var(--blue-dim); color: var(--blue-accent); }
.product-card-icon.agents { background: var(--purple-dim); color: var(--purple-accent); }

.product-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.product-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 20px;
}

.product-card .btn {
  font-size: 0.8125rem;
  padding: 8px 16px;
}

/* ===== CLI Setup Section ===== */
.cli-section {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-default);
  padding: 48px;
}

.cli-header {
  margin-bottom: 32px;
}

.cli-header h2 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.cli-header p {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-primary);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  font-family: var(--font-body);
  text-align: left;
  transition: background var(--transition-fast);
}

.accordion-trigger:hover {
  background: var(--bg-tertiary);
}

.accordion-icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-smooth);
  flex-shrink: 0;
  color: var(--text-secondary);
}

.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
  color: var(--accent);
}

.accordion-item.active .accordion-trigger {
  color: var(--accent);
}

.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-panel-inner {
  padding: 0 20px 20px;
}

.accordion-steps {
  list-style: none;
  counter-reset: step;
}

.accordion-steps li {
  counter-increment: step;
  padding: 10px 0 10px 36px;
  position: relative;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.accordion-steps li::before {
  content: counter(step);
  position: absolute;
  left: 0;
  top: 10px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--text-muted);
}

/* Tabs */
.tabs {
  margin-top: 8px;
}

.tab-list {
  display: flex;
  gap: 2px;
  margin-bottom: 0;
}

.tab-btn {
  padding: 6px 16px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  font-family: var(--font-body);
  transition: all var(--transition-fast);
}

.tab-btn:hover {
  color: var(--text-primary);
}

.tab-btn.active {
  background: var(--bg-tertiary);
  color: var(--accent);
  border-color: var(--border-default);
  border-bottom-color: var(--bg-primary);
  position: relative;
}

.tab-btn.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--bg-primary);
}

.tab-panel {
  display: none;
  background: var(--bg-primary);
  border: 1px solid var(--border-default);
  border-radius: 0 var(--radius-md) var(--radius-md) var(--radius-md);
  overflow: hidden;
}

.tab-panel.active {
  display: block;
}

/* Code Block */
.code-block {
  background: #0d1117;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.code-block code {
  font-family: var(--font-mono);
  font-size: 0.875rem;
  color: var(--accent);
  word-break: break-all;
}

.copy-btn {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  cursor: pointer;
  font-family: var(--font-body);
  transition: all var(--transition-fast);
  white-space: nowrap;
  flex-shrink: 0;
}

.copy-btn:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.init-command {
  margin-top: 16px;
  background: var(--bg-primary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 14px 20px;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  color: var(--orange-accent);
}

/* ===== Launch CTA ===== */
.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: all var(--transition-smooth);
}

.launch-card:hover {
  border-color: var(--text-muted);
}

.launch-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
}

.launch-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  flex: 1;
}

/* ===== Community ===== */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-smooth);
  text-decoration: none;
  color: var(--text-primary);
}

.community-card:hover {
  border-color: var(--accent);
  box-shadow: 0 0 20px var(--accent-dim);
  color: var(--text-primary);
}

.community-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.community-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

/* ===== Grid Cards (Apps / Storefronts pages) ===== */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.card-grid.col2 {
  grid-template-columns: repeat(2, 1fr);
}

.info-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-smooth);
}

.info-card:hover {
  border-color: var(--text-muted);
}

.info-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.info-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ===== Sidebar Layout (Apps & Agents pages) ===== */
.with-sidebar {
  display: flex;
  gap: 0;
  position: relative;
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  padding: 32px 0;
  border-right: 1px solid var(--border-default);
  transition: all var(--transition-smooth);
  background: var(--bg-primary);
  z-index: 10;
}

.sidebar.collapsed {
  width: 0;
  padding: 32px 0;
  border-right: none;
  overflow: hidden;
}

.sidebar-nav {
  list-style: none;
  padding: 0 16px;
}

.sidebar-nav li {
  margin-bottom: 2px;
}

.sidebar-nav a {
  display: block;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.sidebar-nav a:hover,
.sidebar-nav a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-label {
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  padding: 12px 12px 6px;
}

.sidebar-toggle {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 20;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-default);
  color: var(--text-secondary);
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  transition: all var(--transition-fast);
}

.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.main-content {
  flex: 1;
  min-width: 0;
  padding: 40px 48px;
}

/* ===== Page Hero (interior) ===== */
.page-hero {
  padding: 48px 0 40px;
  border-bottom: 1px solid var(--border-default);
  margin-bottom: 48px;
}

.page-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
}

.page-hero p {
  font-size: 1rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 640px;
}

/* ===== Section Headers (interior pages) ===== */
.content-section {
  margin-bottom: 56px;
}

.content-section h2 {
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.content-section > p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  max-width: 640px;
}

/* ===== Protocol Actors (Agents page) ===== */
.actors-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 16px;
}

.actor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  transition: all var(--transition-smooth);
}

.actor-card:hover {
  border-color: var(--text-muted);
}

.actor-card .actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}

.actor-icon.agent { background: var(--accent-dim); color: var(--accent); }
.actor-icon.merchant { background: var(--blue-dim); color: var(--blue-accent); }
.actor-icon.cp { background: var(--purple-dim); color: var(--purple-accent); }
.actor-icon.psp { background: var(--orange-dim); color: var(--orange-accent); }

.actor-card h4 {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.actor-card p {
  font-size: 0.75rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* ===== Status Badge ===== */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 500;
  background: var(--orange-dim);
  color: var(--orange-accent);
  margin-top: 12px;
}

.status-badge::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* ===== Support Categories ===== */
.support-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-smooth);
}

.support-card:hover {
  border-color: var(--text-muted);
}

.support-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.support-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

/* ===== Alerts ===== */
.alert {
  background: var(--blue-dim);
  border: 1px solid rgba(88, 166, 255, 0.2);
  border-radius: var(--radius-md);
  padding: 20px 24px;
  font-size: 0.875rem;
  color: var(--blue-accent);
  line-height: 1.5;
}

.alert strong {
  color: var(--blue-accent);
}

/* ===== Footer ===== */
.site-footer {
  border-top: 1px solid var(--border-default);
  padding: 56px 0 40px;
  margin-top: 40px;
}

