.product-card:hover::before {
  opacity: 1;
}

.product-card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  margin-bottom: 16px;
}

.product-card-icon.apps { background: var(--accent-dim); color: var(--accent); }
.product-card-icon.storefronts { background: var(--blue-dim); color: var(--blue-accent); }
.product-card-icon.agents { background: var(--purple-dim); color: var(--purple-accent); }

.product-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.product-card p {
  font-size: 0.875rem;
