  line-height: 1.6;
  margin-bottom: 20px;
}

.product-card .btn {
  font-size: 0.8125rem;
  padding: 8px 16px;
}

/* ===== CLI Setup Section ===== */
.cli-section {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-default);
  padding: 48px;
}

.cli-header {
  margin-bottom: 32px;
}

.cli-header h2 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.cli-header p {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-primary);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  font-family: var(--font-body);
  text-align: left;
  transition: background var(--transition-fast);
}

.accordion-trigger:hover {
  background: var(--bg-tertiary);
}

.accordion-icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-smooth);
  flex-shrink: 0;
  color: var(--text-secondary);
}

.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
  color: var(--accent);
}

.accordion-item.active .accordion-trigger {
  color: var(--accent);
}

.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-panel-inner {
  padding: 0 20px 20px;
}

.accordion-steps {
  list-style: none;
  counter-reset: step;
}

.accordion-steps li {
  counter-increment: step;
  padding: 10px 0 10px 36px;
  position: relative;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.accordion-steps li::before {
  content: counter(step);
  position: absolute;
  left: 0;
  top: 10px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--text-muted);
}

/* Tabs */
.tabs {
  margin-top: 8px;
}

.tab-list {
  display: flex;
  gap: 2px;
  margin-bottom: 0;
}

.tab-btn {
  padding: 6px 16px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
