  font-weight: 600;
  margin-bottom: 6px;
}

.info-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ===== Sidebar Layout (Apps & Agents pages) ===== */
.with-sidebar {
  display: flex;
  gap: 0;
  position: relative;
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
