  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  padding: 32px 0;
  border-right: 1px solid var(--border-default);
  transition: all var(--transition-smooth);
  background: var(--bg-primary);
  z-index: 10;
}

.sidebar.collapsed {
  width: 0;
  padding: 32px 0;
  border-right: none;
  overflow: hidden;
}

.sidebar-nav {
  list-style: none;
  padding: 0 16px;
}

.sidebar-nav li {
  margin-bottom: 2px;
}

.sidebar-nav a {
