  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  transition: all var(--transition-fast);
}

.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.main-content {
  flex: 1;
  min-width: 0;
  padding: 40px 48px;
}

/* ===== Page Hero (interior) ===== */
.page-hero {
  padding: 48px 0 40px;
  border-bottom: 1px solid var(--border-default);
  margin-bottom: 48px;
}

.page-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
}

.page-hero p {
  font-size: 1rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 640px;
}

/* ===== Section Headers (interior pages) ===== */
.content-section {
  margin-bottom: 56px;
}

.content-section h2 {
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.content-section > p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  max-width: 640px;
}

/* ===== Protocol Actors (Agents page) ===== */
.actors-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 16px;
}

.actor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
  transition: all var(--transition-smooth);
}

.actor-card:hover {
  border-color: var(--text-muted);
}

.actor-card .actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}

.actor-icon.agent { background: var(--accent-dim); color: var(--accent); }
.actor-icon.merchant { background: var(--blue-dim); color: var(--blue-accent); }
.actor-icon.cp { background: var(--purple-dim); color: var(--purple-accent); }
.actor-icon.psp { background: var(--orange-dim); color: var(--orange-accent); }

.actor-card h4 {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.actor-card p {
  font-size: 0.75rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

/* ===== Status Badge ===== */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 500;
  background: var(--orange-dim);
  color: var(--orange-accent);
  margin-top: 12px;
}

.status-badge::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* ===== Support Categories ===== */
.support-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-smooth);
}

.support-card:hover {
  border-color: var(--text-muted);
}

.support-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.support-card p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

/* ===== Alerts ===== */
.alert {
  background: var(--blue-dim);
  border: 1px solid rgba(88, 166, 255, 0.2);
  border-radius: var(--radius-md);
  padding: 20px 24px;
  font-size: 0.875rem;
  color: var(--blue-accent);
  line-height: 1.5;
}

.alert strong {
  color: var(--blue-accent);
}

/* ===== Footer ===== */
.site-footer {
  border-top: 1px solid var(--border-default);
  padding: 56px 0 40px;
  margin-top: 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.footer-col h4 {
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--text-primary);
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 6px;
}

.footer-col a {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  margin-top: 48px;
  padding-top: 24px;
  border-top: 1px solid var(--border-muted);
  text-align: center;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ===== Theme Toggle Icon ===== */
.theme-toggle svg {
  width: 16px;
  height: 16px;
  display: block;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .card-grid { grid-template-columns: repeat(2, 1fr); }
  .product-cards { grid-template-columns: repeat(3, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .actors-diagram { grid-template-columns: repeat(2, 1fr); }
  .support-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .launch-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-hamburger { display: block; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: var(--nav-height);
    left: 0;
    right: 0;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--border-default);
    padding: 12px 24px;
    gap: 2px;
  }
  .nav-links.open a {
    padding: 10px 12px;
    border-radius: var(--radius-sm);
  }

  .product-cards { grid-template-columns: 1fr; }
  .card-grid { grid-template-columns: 1fr; }
  .card-grid.col2 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .actors-diagram { grid-template-columns: 1fr 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }

  .cli-section { padding: 28px 20px; }
  .hero { padding: 56px 0 40px; }

  .sidebar {
    width: 100%;
    position: relative;
    top: 0;
    height: auto;
    border-right: none;
    border-bottom: 1px solid var(--border-default);
    padding: 16px 0;
  }

  .sidebar.collapsed {
    width: 100%;
    padding: 12px 0;
  }

  .with-sidebar { flex-direction: column; }
  .main-content { padding: 24px 0; }
  .sidebar-toggle { top: 8px; left: 8px; }

  .hero-ctas { flex-direction: column; align-items: center; }
}

@media (max-width: 480px) {
  .page-container { padding: 0 16px; }
  .hero h1 { font-size: 1.8rem; }
  .section { padding: 48px 0; }
  .actors-diagram { grid-template-columns: 1fr; }
  .nav-actions .nav-btn:not(.nav-btn-primary) { display: none; }
}
