/* ===== Light Mode Override ===== */
body.light-mode {
  --bg-primary: #ffffff;
  --bg-secondary: #f6f8fa;
  --bg-tertiary: #f0f2f5;
  --bg-card: #ffffff;
  --border-default: #d0d7de;
  --border-muted: #e3e8ef;
  --text-primary: #1f2328;
  --text-secondary: #656d76;
  --text-muted: #8b949e;
  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.06), 0 0 0 1px rgba(0, 0, 0, 0.03);
  --shadow-elevated: 0 8px 24px rgba(0, 0, 0, 0.08), 0 0 0 1px rgba(0, 0, 0, 0.04);
}

body.light-mode .top-nav {
  background: rgba(255, 255, 255, 0.88);
}

body.light-mode .hero h1 {
  background: linear-gradient(135deg, #1f2328 0%, #444d56 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

body.light-mode .code-block {
  background: #f6f8fa;
}

body.light-mode .code-block code {
  color: #0550ae;
}

body.light-mode .init-command {
  background: #f6f8fa;
}

body.light-mode .nav-links a:hover,
body.light-mode .nav-links a.active {
  background: var(--bg-tertiary);
}

